package com.pethop.adoption;
import com.pethop.common.exception.ApiException; import com.pethop.pet.storage.StoredFile; import java.io.*; import java.nio.file.*; import java.util.*; import java.util.regex.Pattern; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.multipart.MultipartFile;
@Component public class LocalDocumentStorage implements DocumentStorage {
 private static final long MAX=10*1024*1024; private static final Pattern SAFE=Pattern.compile("^[0-9a-fA-F-]{36}\\.(pdf|jpg|png|webp)$"); private final Path root;
 public LocalDocumentStorage(@Value("${pethop.storage.local-path}")String root){this.root=Paths.get(root).toAbsolutePath().normalize();}
 public StoredFile store(MultipartFile file)throws IOException{if(file==null||file.isEmpty()||file.getSize()>MAX)throw ApiException.badRequest("El documento debe tener entre 1 y 10 MB.");byte[] data=file.getBytes();String type=type(data);if(type==null)throw ApiException.badRequest("Solo se permiten PDF, JPEG, PNG o WebP.");String name=clean(file.getOriginalFilename());String extension=ext(name);if(!extension.equals(extensionFor(type)))throw ApiException.badRequest("La extensión no coincide con el formato del documento.");Files.createDirectories(root);String relative=UUID.randomUUID()+"."+extension;Files.write(root.resolve(relative),data,StandardOpenOption.CREATE_NEW);return new StoredFile(relative,type,data.length,name);}
 public InputStream open(String path)throws IOException{return Files.newInputStream(resolve(path));} public void delete(String path)throws IOException{Files.deleteIfExists(resolve(path));}
 private Path resolve(String path){if(path==null||!SAFE.matcher(path).matches())throw ApiException.notFound("Documento no encontrado.");Path p=root.resolve(path).normalize();if(!p.getParent().equals(root))throw ApiException.notFound("Documento no encontrado.");return p;}
 private String clean(String name){if(name==null||name.isBlank())throw ApiException.badRequest("El documento debe tener nombre.");String base=Paths.get(name.replace('\\','/')).getFileName().toString();return base.replaceAll("[^\\p{L}\\p{N}._ -]","_");}
 private String ext(String n){int i=n.lastIndexOf('.');return i<0?"":n.substring(i+1).toLowerCase(Locale.ROOT);} private String extensionFor(String t){return switch(t){case "application/pdf"->"pdf";case "image/jpeg"->"jpg";case "image/png"->"png";case "image/webp"->"webp";default->"";};}
 private String type(byte[] d){if(d.length>=5&&d[0]=='%'&&d[1]=='P'&&d[2]=='D'&&d[3]=='F'&&d[4]=='-')return "application/pdf";if(d.length>=3&&(d[0]&255)==255&&(d[1]&255)==216&&(d[2]&255)==255)return "image/jpeg";if(d.length>=8&&(d[0]&255)==137&&d[1]==80&&d[2]==78&&d[3]==71)return "image/png";if(d.length>=12&&d[0]=='R'&&d[1]=='I'&&d[2]=='F'&&d[3]=='F'&&d[8]=='W'&&d[9]=='E'&&d[10]=='B'&&d[11]=='P')return "image/webp";return null;}
}
